// Every migration, in the order it is applied (the order matters: 71001
// runs between 71 and 72). Read by server/src/db.rs via `include!`. The
// versions and SQL are the desktop app's, so its databases open here as
// already migrated.
//
// To add a migration: create server/migrations/NNNN_name.sql AND append a
// line here. Never edit or reorder an existing line or .sql file.
migration_list! {
    (1, "create core schema", "0001_init.sql"),
    (2, "track imported files for duplicate detection", "0002_import_files.sql"),
    (3, "track whole source files for multi-page batch imports", "0003_source_files.sql"),
    (4, "log every import attempt with a real status", "0004_source_file_status.sql"),
    (5, "link imports back to their whole original file", "0005_import_source_file.sql"),
    (6, "store how many punch columns an import's grid needs", "0006_import_max_punches.sql"),
    (7, "add clients, scoped one-to-many under companies", "0007_clients.sql"),
    (8, "clients are many-to-many with companies, not one-to-many", "0008_clients_many_to_many.sql"),
    (9, "store each import's period aggregates instead of recomputing them live", "0009_import_period_aggregates.sql"),
    (10, "split absence minutes into falta (no valid pair) and atraso (short despite a pair)", "0010_import_late_minutes.sql"),
    (11, "count days with a pending (odd) punch count per import", "0011_import_pending_count.sql"),
    (12, "scope source files to their import type (timesheet vs. payment)", "0012_source_file_import_type.sql"),
    (13, "define reusable payment import templates (column mapping only, not execution)", "0013_payment_templates.sql"),
    (14, "let a payment template target a set of sheets instead of a single fixed one", "0014_payment_template_multi_sheet.sql"),
    (15, "split a payment template into per-sheet-group header row + column mapping", "0015_payment_template_groups.sql"),
    (16, "let each company set its own night-shift hour boundaries", "0016_company_night_shift_hours.sql"),
    (17, "add matricula to employees, completing the cpf/matricula/nome identifier precedence", "0017_employee_matricula.sql"),
    (18, "track imported payment shifts, one row per work shift", "0018_payment_shifts.sql"),
    (19, "drop payment_template_groups.header_row — row validity is decided at import time by date-parseability instead", "0019_payment_template_drop_header_row.sql"),
    (20, "drop payment_templates.client_id and decimal_separator — client is now resolved per row via rules, decimal separator was never used", "0020_payment_template_drop_client_and_decimal.sql"),
    (21, "add payment_template_rules — an if/else-if/else chain routing each row to a company/client by a mapped field's value", "0021_payment_template_rules.sql"),
    (22, "normalize payment_shifts.schedule into start/end minutes instead of raw text", "0022_payment_shift_schedule_minutes.sql"),
    (23, "drop payment_templates.sample_file_path/sample_file_name — no longer persisted, only used transiently while building the mapping", "0023_payment_template_drop_sample_file.sql"),
    (24, "add payment_templates.identifier_priority — configurable ordered list of AND'd identifier-field attempts, replacing the hardcoded cpf/matricula/nome precedence", "0024_payment_template_identifier_priority.sql"),
    (25, "add a per-tentativa case-insensitive flag to payment_templates.identifier_priority, matching payment_template_rules' values", "0025_payment_template_identifier_case.sql"),
    (26, "add payment_template_status_rules — an optional if/else-if/else chain deciding a shift's initial status from a mapped field's value", "0026_payment_template_status_rules.sql"),
    (27, "add employee_aliases — possíveis nomes a colaborador can also be matched by during payment import", "0027_employee_aliases.sql"),
    (28, "add companies.night_shift_rule — which rule decides a payment shift counts as noturno against the company's night window", "0028_company_night_shift_rule.sql"),
    (29, "add payment_value_rules — an optional per-company if/else-if/else chain deciding a shift's Valor from its own duration", "0029_company_payment_value_rules.sql"),
    (30, "switch payment_value_rules' threshold from decimal hours to whole minutes", "0030_payment_value_rules_threshold_minutes.sql"),
    (31, "add payment_shifts.previous_shift_id — links a 'pago' row back to the pendente/erro row it replaces, so paying never mutates history", "0031_payment_shift_previous.sql"),
    (32, "add employee_templates — reusable column-mapping templates for the colaboradores import flow, mirroring payment_templates but without company/client routing rules, date parsing, or status rules", "0032_employee_templates.sql"),
    (33, "add employee_template_groups.header_row — marks the last header/title row per sheet group, so import can start right after it", "0033_employee_template_header_row.sql"),
    (34, "backfill employees.cpf to digits-only for any row stored punctuated by the timesheet-PDF-import path, before that path was fixed to normalize like every other write path", "0034_normalize_employee_cpf.sql"),
    (35, "add payment_shifts.extra_data — raw values of columns the template left unmapped, kept for history instead of discarded", "0035_payment_shift_extra_data.sql"),
    (36, "track a payment import's source URL and last-known remote signature, for reimport-when-changed detection", "0036_source_file_url.sql"),
    (37, "add source_url_settings — per-URL opt-out of the automatic remote-change check", "0037_source_url_settings.sql"),
    (38, "add per-URL check interval override and source_url_check_log — full history of the automatic remote-change check, for the Verificação automática page", "0038_source_url_check_tracking.sql"),
    (39, "add source_url_settings.reimport_period_start/end — the Período filters to replay automatically on a detected-change reimport", "0039_source_url_reimport_filters.sql"),
    (40, "add source_url_settings.reimport_template_id — which template to apply on an automatic reimport", "0040_source_url_reimport_template.sql"),
    (41, "add source_url_settings.tracking_enabled — explicit opt-in gate, replacing the old implicit 'any URL-sourced save is tracked' behavior", "0041_source_url_tracking_enabled.sql"),
    (42, "add source_url_reimport_configs — a tracked URL can have multiple independent reimport recipes (template + fixed or relative Período), each flagging its own reimport opportunity", "0042_source_url_reimport_configs.sql"),
    (43, "move check_disabled/check_interval_minutes from source_url_settings (per URL) to source_url_reimport_configs (per config) — each reimport config now runs on its own schedule", "0043_reimport_config_check_settings.sql"),
    (44, "backfill NULL source_url_reimport_configs.check_interval_minutes to 5 — the per-config interval is now mandatory, the global default setting is going away", "0044_reimport_config_interval_required.sql"),
    (45, "add payment_shifts.edited_manually and payment_settings.keep_manual_edits — reprocessing a duplicate payment shift can now skip one whose current row was a deliberate manual action instead of silently superseding it", "0045_payment_shifts_manual_edits.sql"),
    (46, "add source_url_reimport_configs.keep_manual_edits — each reimport config now carries its own choice of whether to skip manually-edited matches, captured at creation and editable on Verificação automática", "0046_reimport_config_keep_manual_edits.sql"),
    (47, "preserve whether each template sheet is included or disabled, so hidden sheets reappear when editing a saved template", "0047_template_sheet_included.sql"),
    (48, "add payment_value_rules.conditions_json — narrows a pay-value rule step to shifts matching Data/Local/Função/Horário conditions before its duration check runs", "0048_payment_value_rules_conditions.sql"),
    (49, "add payment_settings.visible_columns_json — which columns of the Pagamentos table are shown, NULL meaning all of them", "0049_payment_settings_visible_columns.sql"),
    (50, "add accepted_file_kinds_json to payment_templates and employee_templates — a template can now accept more than one file format at import time", "0050_template_accepted_file_kinds.sql"),
    (51, "add payment_export_templates — user-designed layouts (columns, colors, grouping, subtotal rows) for exporting payment shifts to a styled .xlsx", "0051_payment_export_templates.sql"),
    (52, "add deleted_at to payment_shifts — 'Remover' soft-deletes a shift's whole history chain instead of physically deleting it, so a later reimport can recognize and flag it instead of silently recreating it", "0052_payment_shifts_soft_delete.sql"),
    (53, "add source_url_check_diffs and last_deep_check_* signature columns — a background check that finds a header change now also downloads, parses and diffs against what's saved, recording exactly what changed instead of just 'changed'", "0053_source_url_check_diffs.sql"),
    (54, "add source_url_settings.last_deep_check_result — the deep diff, not the header check, now decides what a check's Resultado column shows", "0054_deep_check_drives_result.sql"),
    (55, "add source_url_settings.last_deep_check_log_id — a check that reuses the cached deep-check verdict now copies that run's diff rows onto its own check_log_id too, so Detalhes is never blank just because the download/parse was skipped", "0055_deep_check_log_id.sql"),
    (56, "add payment_shifts.source_row_number/source_sheet_name (indexed) — promoted out of extra_data so the deep-check diff can look up 'what shift used to sit at this row/aba' when an identity-field edit breaks the usual identity match", "0056_payment_shift_source_position.sql"),
    (57, "backfill payment_shifts.source_row_number/source_sheet_name from extra_data's old 'linha de origem'/'aba de origem' text for every row imported before 0056 — otherwise the deep-check position fallback finds nothing for any pre-existing shift", "0057_backfill_payment_shift_source_position.sql"),
    (58, "add source_url_reimport_configs.auto_apply_enabled/auto_apply_overwrite_manual_edits/auto_apply_overwrite_paid and source_url_check_diffs.applied — lets a reimport config write a change the automatic verification finds straight to payment_shifts instead of only leaving it pending for manual review", "0058_reimport_auto_apply.sql"),
    (59, "add payment_template_rules.conditions_json/payment_template_status_rules.conditions_json — a routing/status rule can test several mapped fields at once (AND), not just one", "0059_rule_conditions.sql"),
    (60, "add payment_shifts.client_id/company_id (backfilled from the current employee) — snapshots which client/company a turno belonged to at import time instead of deriving it live through employees, so moving an employee to a different client later doesn't retroactively rewrite historical turnos", "0060_payment_shift_client_snapshot.sql"),
    (61, "same as 0060, for imports (Cartão Ponto) instead of payment_shifts", "0061_import_client_snapshot.sql"),
    (62, "clients gain the same optional night-shift window/rule and pay-value-chain overrides companies have (client_payment_value_rules mirrors payment_value_rules) — NULL/empty means \"inherit the company's\", client wins when set", "0062_client_payment_rules.sql"),
    (63, "add source_url_check_log_configs — which reimport configs a check attempt actually evaluated, so due-ness and history become per-config instead of shared per URL", "0063_source_url_check_log_configs.sql"),
    (64, "source_url_check_log_configs gains template_id/template_name/period_start/period_end — a snapshot of what a config's check attempt actually used, since the live config can be edited or deleted afterward", "0064_check_log_config_snapshot.sql"),
    (65, "source_url_check_diffs gains dismissed_at — lets the user acknowledge (\"Visto\") a specific diff/error row without it counting toward the pending-updates banner, without suppressing a later occurrence of the same problem", "0065_check_diffs_dismissed.sql"),
    (66, "add dismissed_diff_fingerprints — content-based \"Visto\" suppression, so a later check whose diff has identical content to one already dismissed is auto-dismissed on arrival instead of re-alerting", "0066_dismissed_diff_fingerprints.sql"),
    (67, "employees.UNIQUE(company_id, cpf) widened to (company_id, client_id, cpf) — the old constraint predated client_id and blocked creating/moving an employee into a company that already has a different employee sharing that CPF under a different client, even though the app's own duplicate checks are already client-scoped", "0067_employee_unique_per_client.sql"),
    (68, "add roles/role_aliases — função moves from free-text payment_shifts.role to a real cadastro (scoped per company, mirroring employees/employee_aliases), plus payment_shifts.role_id and a backfill linking every existing shift's role text to a função", "0068_roles.sql"),
    (69, "drop payment_shifts.role — role_id (backfilled 100% in 0068) is now the only representation of a turno's função, exactly mirroring how employee_id (not a redundant employee-name text column) already works", "0069_payment_shift_role_fk_only.sql"),
    (70, "backfill payment_shifts.edited_manually for markPaymentShiftPaid/revertPaymentShiftToPending rows written before those two transitions stopped forcing it to 1 — only a genuine editPaymentShift hop anywhere in a row's ancestry should still read edited_manually", "0070_backfill_edited_manually.sql"),
    (71, "employees.UNIQUE(company_id, client_id, cpf) narrowed to UNIQUE(client_id, cpf) — a colaborador is one person per cliente now, not one person per (cliente, empresa); company_id/matricula move off employees onto the new employee_companies (one row per empresa a colaborador is linked to), fixing the same person showing up as a separate duplicate colaborador per empresa", "0071_employee_company_link.sql"),
    (71001, "one-time cleanup of 0071's leftover TEMP TABLE employee_canonical, which otherwise collides with 0072's own — added as a separate migration (not folded into 0072) because 0072 was already applied on real installs before this collision was found; positioned here in the Vec, not by its version number, so it still runs between 0071 and 0072 for a fresh install", "0071b_employee_canonical_temp_cleanup.sql"),
    (72, "employees.UNIQUE(client_id, cpf) narrowed to UNIQUE(cpf) — a colaborador is one person globally now, not one person per cliente; employee_companies (employee_id, company_id, matricula) replaced by employee_client_companies (employee_id, client_id, company_id, matricula), since a empresa can already serve more than one cliente, so a colaborador's empresa link has to say which cliente it's for", "0072_employee_client_link.sql"),
    (73, "one-time cleanup: merges employees rows sharing the exact same name (case/whitespace-insensitive) but different CPFs — 0072's CPF-based merge can't catch these since the CPFs themselves differ; user-confirmed these are genuinely the same person (data-entry mistake on the CPF), not a general auto-merge rule", "0073_merge_duplicate_names.sql"),
    (74, "adds payment_audits table for the Conferência de Pagamentos feature — records manual bank-statement verification of paid shifts, separate from payment_shifts since only the erro outcome is a real state transition", "0074_payment_audits.sql"),
    (75, "adds employee_pix_keys — a colaborador can have multiple PIX keys, each with an automatically detected but user-editable type", "0075_employee_pix_keys.sql"),
    (76, "adds payment_pdf_templates — user-designed layouts (columns, colors, grouping, subtotal rows) for exporting payment shifts to a styled PDF, the PDF counterpart of payment_export_templates", "0076_payment_pdf_templates.sql"),
    (77, "payment_shifts.previous_shift_id becomes UNIQUE — a shift has at most one successor, so two writers acting on the same shift at once can't fork its history; any fork already in the data is repaired first by detaching every successor but the earliest (nothing deleted)", "0077_unique_previous_shift.sql"),
    (78, "who saved the spreadsheet version a remote check looked at (saved_by/saved_at, from the file's own properties) on source_url_check_log, and on each diff the one who saved the version where that change first showed up", "0078_check_saved_by.sql"),
    (79, "who can sign in and what each person can do: access_profiles (per-area none/view/edit plus export, AI and user management; a fixed Admin) and app_users (e-mail and profile); the server's initial admins stay in its configuration", "0079_access_profiles.sql"),
    (80, "activity_log: who changed what and when, with the before/after of each field, kept forever; known_users (the name each person goes by); payment_shifts.created_by (who wrote each version of a turno)", "0080_activity_log.sql"),
}
